  "version": 1,
  "tasks": [
    {
      "id": "define_slo",
      "description": "Define SLO targets for the checkout service",
      "action": "define",
      "target": "SLOs",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "checkout service is deployed",
          "fact": "checkout_service_deployed",
          "established_by": "env"
        }
      ]
    },
    {
      "id": "run_load_test",
      "description": "Run k6 ramp-up test from 10 to 500 RPS over 10 min",
      "action": "run_test",
      "target": "k6",
      "risk_class": "high",
      "rollback": {
        "trigger": "test execution fails",
        "action": "abort test and revert changes",
        "safety_guard": "ensure no lingering load on service"
      },
      "verification": {
        "what": "SLO metrics collected",
        "how": "check Prometheus metrics",
        "expected": "p99 latency <500ms and error rate <0.1%"
      },
      "preconditions": [
        {
          "description": "k6 is installed and configured",
          "fact": "k6_ready",
          "established_by": "define_slo"
        }
      ]
    },
    {
      "id": "collect_metrics",
      "description": "Collect Prometheus metrics after the load test",
      "action": "collect",
      "target": "Prometheus",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "load test has been executed",
          "fact": "load_test_completed",
          "established_by": "run_load_test"
        }
      ]
    },
    {
      "id": "analyze_bottlenecks",
      "description": "Analyze metrics to identify bottlenecks",
      "action": "analyze",
      "target": "metrics",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Prometheus metrics have been collected",
          "fact": "metrics_collected",
          "established_by": "collect_metrics"
        }
      ]
    },
    {
      "id": "right_size_hpa",
      "description": "Right-size HPA limits based on analysis",
      "action": "update",
      "target": "HPA",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "bottlenecks have been identified",
          "fact": "bottlenecks_analyzed",
          "established_by": "analyze_bottlenecks"
        }
      ]
    },
    {
      "id": "ret_test",
      "description": "Re-test to confirm SLOs hold at target load",
      "action": "run_test",
      "target": "k6",
      "risk_class": "high",
      "rollback": {
        "trigger": "re-test fails",
        "action": "reset HPA limits",
        "safety_guard": "monitor service stability"
      },
      "verification": {
        "what": "SLO metrics confirmed",
        "how": "check Prometheus metrics",
        "expected": "p99 latency <500ms and error rate <0.1%"
      },
      "preconditions": [
        {
          "description": "HPA limits have been updated",
          "fact": "hpa_limits_updated",
          "established_by": "right_size_hpa"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "define_slo",
      "to_task": "run_load_test",
      "kind": "hard"
    },
    {
      "from_task": "run_load_test",
      "to_task": "collect_metrics",
      "kind": "hard"
    },
    {
      "from_task": "collect_metrics",
      "to_task": "analyze_bottlenecks",
      "kind": "hard"
    },
    {
      "from_task": "analyze_bottlenecks",
      "to_task": "right_size_hpa",
      "kind": "hard"
    },
    {
      "from_task": "right_size_hpa",
      "to_task": "ret_test",
      "kind": "hard"
    }
  ]
}
